"""Text from PDFs that carry real text (statements, exports and invoices generated by software), standard library only.

Handles the common encodings (FlateDecode, ASCII85Decode, both chained) and the text operators Tj, TJ, ' and ".
Scanned PDFs (a photo inside a PDF) have no text; `pdf_text` returns "" for those and the file is kept as evidence.
"""
import base64
import re
import zlib

_STREAM = re.compile(rb"stream\r?\n")
_TEXT = re.compile(rb"\((?P<s>(?:\\.|[^\\)])*)\)\s*(?:Tj|'|\")|\[(?P<a>(?:\\.|[^\]])*)\]\s*TJ|(?P<br>T\*|Td|TD|Tm|ET)", re.S)
_ESC = {b"n": b"\n", b"r": b"", b"t": b" ", b"b": b"", b"f": b"", b"(": b"(", b")": b")", b"\\": b"\\"}


def _unescape(s: bytes) -> bytes:
    def one(m):
        e = m.group(1)
        if e[:1].isdigit():
            return bytes([int(e, 8) & 0xFF])
        return _ESC.get(e, e)
    return re.sub(rb"\\([0-7]{1,3}|.)", one, s, flags=re.S)


def _decode(filters: bytes, raw: bytes) -> bytes | None:
    for f in re.findall(rb"/(ASCII85Decode|A85|FlateDecode|Fl)\b", filters):
        if f in (b"ASCII85Decode", b"A85"):
            body = raw.strip()
            body = body[2:] if body.startswith(b"<~") else body
            body = body[:-2] if body.endswith(b"~>") else body
            raw = base64.a85decode(body)
        else:
            raw = zlib.decompress(raw)
    return raw


def pdf_text(data: bytes) -> str:
    lines = []
    for m in _STREAM.finditer(data):
        head = data[max(0, m.start() - 400):m.start()]
        head = head[head.rfind(b"<<"):] if b"<<" in head else head
        end = data.find(b"endstream", m.end())
        if end < 0:
            continue
        raw = data[m.end():end].rstrip(b"\r\n")
        try:
            body = _decode(head, raw)
        except Exception:
            continue
        if b"BT" not in body:
            continue
        cur = []
        for t in _TEXT.finditer(body):
            if t.group("s") is not None:
                cur.append(_unescape(t.group("s")))
            elif t.group("a") is not None:
                cur.append(b"".join(_unescape(x) for x in re.findall(rb"\(((?:\\.|[^\\)])*)\)", t.group("a"))))
            elif cur:
                lines.append(b"".join(cur).decode("latin-1"))
                cur = []
        if cur:
            lines.append(b"".join(cur).decode("latin-1"))
    return "\n".join(line.rstrip() for line in lines if line.strip())
